import{_ as i,l,o as e,c,v as o,p as s,x as r,d as m,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"过度提交","description":"","frontmatter":{"title":"过度提交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overcommit.md","filePath":"cs/overcommit.md","lastUpdated":1789023840000}'),p={name:"cs/overcommit.md"};function A(h,a,E,_,f,u){const t=l("Mermaid");return e(),c("div",null,[a[1]||(a[1]=o('<h1 id="过度提交" tabindex="-1">过度提交 <a class="header-anchor" href="#过度提交" aria-label="Permalink to &quot;过度提交&quot;">​</a></h1><div class="epigraph"><p>内核可以允许虚存承诺之和大于 RAM 加 swap：多数页从未被写满；一旦同时触碰，OOM 才出现。</p><footer>—— 据 Silberschatz 对分配与提交的区分；Linux overcommit 策略的整理</footer></div><p><a href="/cs/oom-killer">上一课</a>在真正缺帧时杀人。<a href="/cs/brk-heap">brk 与堆</a>升高水位并不立刻占帧。<a href="/cs/demand-paging">按需调页</a>把占帧推迟到访问。缺口是<strong>承诺会计</strong>：<code>malloc</code>/<code>mmap</code> 成功只表示 VMA 记下了，是否计入「保证能配到的帧」，由过度提交策略决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>严格提交：每次扩大匿名区都扣减「剩余可保证页」（RAM+swap−已提交）。稀疏堆、巨大稀疏数组会立刻失败，尽管工作集很小。宽松提交：几乎总成功，把风险推到缺页与 OOM。启发式：看空闲与可回收文件页，允许一定倍率。缺口不是 CLOCK，而是用户接口何时返回 ENOMEM，何时把失败藏到稍后的故障。</p><p>本课不把 <code>vm.overcommit_memory</code> 的三个整数当唯一真理，只作策略对照。</p><p><span class="marginnote">提交的是匿名与私有写潜力；共享只读文件通常不按「每映射一份物理页」记账。fork 的 COW 会把承诺翻倍——下一课用写时复制推迟真拷贝，但会计可能已经加倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核维护 committed 计数。策略 A：超过 RAM+swap 则 <code>mmap</code>/<code>brk</code> 失败。策略 B：允许超过，OOM 兜底。策略 C：按空闲估计。用户要「真保证」可用 mlock 或关闭过度提交，代价是必须现在就有帧。与抖动对照：过度提交提高多道的虚上限，使 ΣW 更容易在运行期爆炸。</p>',9)),(e(),s(n,null,{default:r(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22brk%2Fmmap%22%5D%20--%3E%20ACC%5B%22%E6%8F%90%E4%BA%A4%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20ACC%20--%3E%7C%E4%B8%A5%E6%A0%BC%E4%B8%94%E6%BB%A1%7C%20ENOMEM%5B%22%E7%8E%B0%E5%9C%A8%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20ACC%20--%3E%7C%E5%AE%BD%E6%9D%BE%7C%20OK%5B%22VMA%20%E6%88%90%E5%8A%9F%22%5D%0A%20%20OK%20--%3E%20LATER%5B%22%E8%A7%A6%E7%A2%B0%E6%97%B6%E7%BC%BA%E9%A1%B5%2FOOM%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过度提交把「虚存接口」和「物理保证」拆开，让稀疏数据结构便宜。它解释了为何 OOM 发生在运行很久之后，而不是 malloc 那一行。不要把这写成攻击教程；只说明会计与按需的组合会产生延迟失败。文件页可回收，常不按一对一计入匿名承诺。</p><p><a href="/cs/paging-vm">分页</a> 仍只在缺页时要帧；会计是 OS 策略层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 memcg 的 per-group 提交限额全文。不保证用户态能可移植地查询「还剩多少保证」。下一课 <code>fork</code> 若立刻复制全部页，再严格的会计也会在创建进程时爆掉——于是写时复制把复制推迟，同时把承诺问题变得更尖锐。</p><p>后课默认：VMA 可以大于物理。<code>fork</code> 的副本若立刻占两倍帧则不可接受，下一课写时复制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>提交会计决定「现在失败」还是「以后 OOM」。</li><li>按需加上宽松提交，使稀疏堆可行。</li><li>fork 的复制代价是 COW 的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Linux overcommit 文档；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const O=i(p,[["render",A]]);export{C as __pageData,O as default};
